const select=document.querySelector('#animal-select');select.innerHTML=ANIMALS.map(a=>'<option value="'+a.id+'">'+a.id+' — '+a.name+'</option>').join('');
const wanted=Number(new URLSearchParams(location.search).get('id')||1);select.value=String(ANIMALS.some(a=>a.id===wanted)?wanted:1);
const scene=document.createElement('a-scene');scene.setAttribute('embedded','');scene.setAttribute('xr-mode-ui','enabled: false');scene.setAttribute('vr-mode-ui','enabled: false');scene.setAttribute('renderer','antialias: true; colorManagement: true');scene.setAttribute('background','color: #e8efdf');
scene.innerHTML='<a-entity camera="fov: 46" position="0 1.1 3.7" rotation="-8 0 0" look-controls="enabled: false" wasd-controls="enabled: false"></a-entity><a-light type="ambient" intensity="0.55"></a-light><a-light type="directional" position="-2 4 3" intensity="0.8"></a-light><a-circle radius="1.6" rotation="-90 0 0" material="shader: flat; color: #d8e2c9" position="0 -.01 0"></a-circle>';
for(const a of ANIMALS){const holder=document.createElement('a-entity');holder.id='animal-model-'+a.id;const model=document.createElement('a-entity');model.dataset.animalId=a.id;model.setAttribute('rotation','0 35 0');model.setAttribute('fit-animal','size: 1.65');model.setAttribute('gltf-model',a.model);model.addEventListener('animal-ready',()=>{if(Number(select.value)===a.id)document.querySelector('#preview-error').textContent='';});model.addEventListener('model-error',()=>{model.dataset.failed='true';if(Number(select.value)===a.id)document.querySelector('#preview-error').textContent='Không tải được mô hình. Kiểm tra file trong assets/models.';});holder.append(model);scene.append(holder);}
document.querySelector('#scene-container').append(scene);
function pick(){const id=Number(select.value);scene.querySelectorAll('[id^="animal-model-"]').forEach(h=>h.object3D.visible=h.id==='animal-model-'+id);document.dispatchEvent(new CustomEvent('ar-tracking',{detail:{found:true,id}}));const model=document.querySelector('#animal-model-'+id+' [gltf-model]');document.querySelector('#preview-error').textContent=model.dataset.failed?'Không tải được mô hình.':model.dataset.ready?'':'Đang tải mô hình…';}
select.addEventListener('change',pick);pick();